arguments.content:
/* ChartPulse - Shared Styles */
:root {
  --bg: #0F0F0F;
  --bg-elev: #161618;
  --bg-elev-2: #1c1c20;
  --bg-card: #1a1a1f;
  --border: #2a2a30;
  --border-light: #33333a;
  --text: #e8e8ec;
  --text-muted: #8b8b94;
  --text-dim: #5f5f68;
  --accent: #2962FF;
  --accent-hover: #1e4fd6;
  --green: #26a69a;
  --green-bright: #4ade80;
  --red: #F7525F;
  --red-dark: #d9354a;
  --yellow: #f9c440;
  --purple: #a855f7;
  --radius: 6px;
  --font-sans: 'Inter', system-ui, -apple-system, sans-serif;
  --font-mono: 'JetBrains Mono', 'Menlo', monospace;
}

* { box-sizing: border-box; margin: 0; padding: 0; }

html, body {
  background: var(--bg);
  color: var(--text);
  font-family: var(--font-sans);
  font-size: 14px;
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
}

a { color: inherit; text-decoration: none; }
button { background: none; border: none; color: inherit; font: inherit; cursor: pointer; }
input { font: inherit; color: inherit; background: none; border: none; outline: none; }

.mono { font-family: var(--font-mono); font-variant-numeric: tabular-nums; }
.green { color: var(--green-bright); }
.red { color: var(--red); }
.muted { color: var(--text-muted); }
.dim { color: var(--text-dim); }

/* ========== HEADER ========== */
.header {
  position: sticky; top: 0; z-index: 100;
  background: rgba(15, 15, 15, 0.85);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--border);
  height: 56px;
  display: flex; align-items: center;
  padding: 0 20px;
}
.header-inner {
  width: 100%; max-width: 1600px; margin: 0 auto;
  display: flex; align-items: center; gap: 28px;
}
.logo {
  display: flex; align-items: center; gap: 8px;
  font-weight: 700; font-size: 17px; letter-spacing: -0.02em;
}
.logo-mark {
  width: 28px; height: 28px;
  background: linear-gradient(135deg, var(--accent), #5b8cff);
  border-radius: 7px;
  display: flex; align-items: center; justify-content: center;
  color: white;
}
.nav { display: flex; align-items: center; gap: 4px; }
.nav a {
  padding: 8px 12px;
  font-size: 13px;
  color: var(--text-muted);
  border-radius: 5px;
  transition: all 150ms;
  font-weight: 500;
}
.nav a:hover { color: var(--text); background: var(--bg-elev); }
.nav a.active { color: var(--text); }
.header-search {
  flex: 1; max-width: 320px;
  background: var(--bg-elev);
  border: 1px solid var(--border);
  border-radius: 6px;
  padding: 7px 12px;
  display: flex; align-items: center; gap: 8px;
  color: var(--text-dim);
  font-size: 13px;
}
.header-search input { flex: 1; }
.header-search kbd {
  background: var(--bg-elev-2);
  padding: 2px 6px; border-radius: 3px;
  font-size: 11px; font-family: var(--font-mono);
  color: var(--text-dim);
  border: 1px solid var(--border);
}
.header-actions { display: flex; align-items: center; gap: 8px; margin-left: auto; }
.icon-btn {
  width: 34px; height: 34px;
  display: flex; align-items: center; justify-content: center;
  border-radius: 6px;
  color: var(--text-muted);
  transition: all 150ms;
}
.icon-btn:hover { background: var(--bg-elev); color: var(--text); }

.btn {
  display: inline-flex; align-items: center; gap: 6px;
  padding: 8px 14px;
  border-radius: 6px;
  font-size: 13px; font-weight: 600;
  transition: all 150ms;
  cursor: pointer;
}
.btn-primary { background: var(--accent); color: white; }
.btn-primary:hover { background: var(--accent-hover); }
.btn-ghost { color: var(--text); border: 1px solid var(--border); }
.btn-ghost:hover { background: var(--bg-elev); border-color: var(--border-light); }
.btn-sm { padding: 5px 10px; font-size: 12px; }

/* ========== TICKER STRIP ========== */
.ticker-strip {
  background: var(--bg-elev);
  border-bottom: 1px solid var(--border);
  height: 36px;
  overflow: hidden;
  position: relative;
}
.ticker-track {
  display: flex; align-items: center; gap: 28px;
  height: 100%; padding: 0 20px;
  white-space: nowrap;
  animation: ticker 60s linear infinite;
}
@keyframes ticker {
  0% { transform: translateX(0); }
  100% { transform: translateX(-50%); }
}
.ticker-item {
  display: inline-flex; align-items: center; gap: 8px;
  font-size: 12px;
}
.ticker-item .sym { color: var(--text-muted); font-weight: 600; }
.ticker-item .price { font-family: var(--font-mono); }

/* ========== LAYOUT ========== */
.container {
  max-width: 1600px;
  margin: 0 auto;
  padding: 0 20px;
}
.section { padding: 32px 0; }
.section-header {
  display: flex; align-items: flex-end; justify-content: space-between;
  margin-bottom: 20px;
  flex-wrap: wrap; gap: 12px;
}
.section-header h2 {
  font-size: 22px; font-weight: 700; letter-spacing: -0.02em;
}
.section-header .sub { font-size: 13px; color: var(--text-muted); margin-top: 4px; }
.section-header a.more {
  color: var(--accent); font-size: 13px; font-weight: 500;
  display: inline-flex; align-items: center; gap: 4px;
}

/* ========== TABS ========== */
.tabs {
  display: flex; align-items: center; gap: 2px;
  background: var(--bg-elev);
  padding: 3px;
  border-radius: 7px;
  border: 1px solid var(--border);
}
.tabs button {
  padding: 6px 12px;
  font-size: 12px; font-weight: 500;
  color: var(--text-muted);
  border-radius: 5px;
  transition: all 150ms;
  white-space: nowrap;
}
.tabs button:hover { color: var(--text); }
.tabs button.active {
  background: var(--bg-elev-2);
  color: var(--text);
  box-shadow: 0 1px 0 rgba(255,255,255,0.05);
}
.tabs.tabs-underline {
  background: none; border: none; padding: 0;
  border-bottom: 1px solid var(--border);
  border-radius: 0;
  gap: 0;
}
.tabs.tabs-underline button {
  padding: 12px 16px;
  border-radius: 0;
  border-bottom: 2px solid transparent;
  margin-bottom: -1px;
  font-size: 13px;
}
.tabs.tabs-underline button.active {
  background: none;
  color: var(--text);
  border-bottom-color: var(--accent);
  box-shadow: none;
}

/* ========== CARDS ========== */
.card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: 10px;
  overflow: hidden;
}
.card-pad { padding: 18px; }

/* ========== HERO ========== */
.hero {
  position: relative;
  padding: 80px 0 60px;
  background:
    radial-gradient(ellipse 80% 50% at 50% 0%, rgba(41,98,255,0.18), transparent),
    radial-gradient(ellipse 60% 40% at 100% 100%, rgba(168,85,247,0.08), transparent);
  overflow: hidden;
}
.hero::before {
  content: '';
  position: absolute; inset: 0;
  background-image:
    linear-gradient(rgba(255,255,255,0.025) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255,255,255,0.025) 1px, transparent 1px);
  background-size: 50px 50px;
  mask-image: radial-gradient(ellipse 70% 60% at 50% 30%, black 30%, transparent 70%);
  pointer-events: none;
}
.hero-inner { position: relative; text-align: center; max-width: 880px; margin: 0 auto; }
.hero-badge {
  display: inline-flex; align-items: center; gap: 8px;
  padding: 6px 14px;
  background: rgba(41,98,255,0.12);
  border: 1px solid rgba(41,98,255,0.3);
  border-radius: 100px;
  font-size: 12px; font-weight: 500;
  color: #7da7ff;
  margin-bottom: 24px;
}
.hero-badge .dot {
  width: 6px; height: 6px; border-radius: 50%;
  background: var(--green-bright);
  box-shadow: 0 0 8px var(--green-bright);
}
.hero h1 {
  font-size: 64px; font-weight: 700;
  letter-spacing: -0.04em; line-height: 1.05;
  margin-bottom: 20px;
}
.hero h1 .accent {
  background: linear-gradient(135deg, #5b8cff, #a855f7);
  -webkit-background-clip: text; -webkit-text-fill-color: transparent;
}
.hero p.lede {
  font-size: 18px; color: var(--text-muted);
  max-width: 620px; margin: 0 auto 32px;
}
.hero-cta { display: flex; justify-content: center; gap: 12px; flex-wrap: wrap; }
.hero-cta .btn { padding: 12px 22px; font-size: 14px; }

/* ========== MARKET PILLS ========== */
.market-pills {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: 12px;
  margin-top: 28px;
}
.pill {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 12px 14px;
  display: flex; align-items: center; justify-content: space-between;
  gap: 12px;
  transition: border-color 150ms;
}
.pill:hover { border-color: var(--border-light); }
.pill .label {
  font-size: 12px; color: var(--text-muted); margin-bottom: 2px;
  text-transform: uppercase; letter-spacing: 0.04em;
  font-weight: 500;
}
.pill .ticker { font-size: 12px; color: var(--text-dim); }
.pill .price { font-family: var(--font-mono); font-size: 15px; font-weight: 600; }
.pill .chg { font-size: 12px; font-weight: 600; }
.pill svg.spark { width: 60px; height: 28px; flex-shrink: 0; }

/* ========== TABLES ========== */
.table {
  width: 100%;
  border-collapse: collapse;
  font-size: 13px;
}
.table th {
  text-align: left;
  font-size: 11px; font-weight: 500;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.05em;
  padding: 10px 12px;
  border-bottom: 1px solid var(--border);
  background: var(--bg-elev);
}
.table td {
  padding: 12px;
  border-bottom: 1px solid var(--border);
}
.table tr:last-child td { border-bottom: none; }
.table tr:hover td { background: rgba(255,255,255,0.02); }
.table .num { font-family: var(--font-mono); text-align: right; font-variant-numeric: tabular-nums; }
.sym-cell { display: flex; align-items: center; gap: 10px; }
.sym-icon {
  width: 28px; height: 28px;
  border-radius: 50%;
  display: flex; align-items: center; justify-content: center;
  font-size: 11px; font-weight: 700;
  background: var(--bg-elev-2);
  color: var(--text);
  flex-shrink: 0;
}

/* Color icons */
.ic-spx { background: linear-gradient(135deg, #1e3a8a, #3b82f6); color: #fff; }
.ic-ndx { background: linear-gradient(135deg, #064e3b, #10b981); color: #fff; }
.ic-djia { background: linear-gradient(135deg, #581c87, #a855f7); color: #fff; }
.ic-aapl { background: #fff; color: #000; }
.ic-tsla { background: #cc0000; color: #fff; }
.ic-nflx { background: #e50914; color: #fff; }
.ic-amd { background: #000; color: #fff; border: 1px solid #444; }
.ic-nvda { background: #76b900; color: #000; }
.ic-msft { background: #00a4ef; color: #fff; }
.ic-amzn { background: #ff9900; color: #000; }
.ic-goog { background: #4285f4; color: #fff; }
.ic-btc { background: #f7931a; color: #fff; }
.ic-eth { background: #627eea; color: #fff; }
.ic-oil { background: #1f2937; color: #fbbf24; }
.ic-gold { background: linear-gradient(135deg, #b45309, #f59e0b); color: #fff; }
.ic-eur { background: #003399; color: #ffcc00; }
.ic-gbp { background: #c8102e; color: #fff; }

/* ========== BADGES ========== */
.badge {
  display: inline-flex; align-items: center; gap: 4px;
  padding: 2px 8px;
  border-radius: 4px;
  font-size: 11px; font-weight: 600;
  font-family: var(--font-mono);
}
.badge-up { background: rgba(74,222,128,0.12); color: var(--green-bright); }
.badge-down { background: rgba(247,82,95,0.12); color: var(--red); }
.badge-flat { background: var(--bg-elev-2); color: var(--text-muted); }

.tier-badge {
  display: inline-flex; align-items: center; gap: 4px;
  padding: 3px 8px; border-radius: 4px;
  font-size: 10px; font-weight: 700; text-transform: uppercase; letter-spacing: 0.05em;
}
.tier-platinum { background: linear-gradient(135deg, #94a3b8, #cbd5e1); color: #0f172a; }
.tier-gold { background: linear-gradient(135deg, #b45309, #f59e0b); color: #fff; }
.tier-silver { background: linear-gradient(135deg, #475569, #64748b); color: #fff; }

/* ========== FOOTER ========== */
.footer {
  background: var(--bg-elev);
  border-top: 1px solid var(--border);
  margin-top: 60px;
  padding: 60px 0 30px;
}
.footer-grid {
  display: grid;
  grid-template-columns: 2fr repeat(5, 1fr);
  gap: 40px;
  margin-bottom: 40px;
}
.footer h4 {
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--text-muted);
  margin-bottom: 14px;
  font-weight: 600;
}
.footer ul { list-style: none; display: flex; flex-direction: column; gap: 8px; }
.footer a { font-size: 13px; color: var(--text); transition: color 150ms; }
.footer a:hover { color: var(--accent); }
.footer-brand p { font-size: 13px; color: var(--text-muted); max-width: 280px; margin-top: 12px; }
.footer-bottom {
  border-top: 1px solid var(--border);
  padding-top: 24px;
  display: flex; justify-content: space-between; align-items: center;
  font-size: 12px; color: var(--text-muted);
  flex-wrap: wrap; gap: 12px;
}

/* ========== HOMEPAGE GRIDS ========== */
.grid-3 { display: grid; grid-template-columns: repeat(3, 1fr); gap: 16px; }
.grid-2 { display: grid; grid-template-columns: repeat(2, 1fr); gap: 16px; }
.grid-4 { display: grid; grid-template-columns: repeat(4, 1fr); gap: 16px; }

.idea-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: 10px;
  overflow: hidden;
  transition: all 200ms;
}
.idea-card:hover { border-color: var(--border-light); transform: translateY(-2px); }
.idea-thumb {
  height: 180px;
  background: var(--bg-elev-2);
  position: relative;
  overflow: hidden;
}
.idea-thumb svg { width: 100%; height: 100%; }
.idea-side {
  position: absolute; top: 10px; left: 10px;
  display: inline-flex; align-items: center; gap: 4px;
  padding: 3px 8px; border-radius: 4px;
  font-size: 11px; font-weight: 700;
  background: rgba(0,0,0,0.6); backdrop-filter: blur(4px);
}
.idea-side.long { color: var(--green-bright); }
.idea-side.short { color: var(--red); }
.idea-body { padding: 14px; }
.idea-title { font-size: 14px; font-weight: 600; margin-bottom: 6px; line-height: 1.4; }
.idea-meta { display: flex; align-items: center; gap: 8px; font-size: 12px; color: var(--text-muted); }
.avatar {
  width: 22px; height: 22px; border-radius: 50%;
  background: var(--accent);
  display: flex; align-items: center; justify-content: center;
  font-size: 10px; font-weight: 700; color: white;
  flex-shrink: 0;
}
.idea-stats {
  display: flex; gap: 14px; margin-top: 10px;
  padding-top: 10px; border-top: 1px solid var(--border);
  font-size: 12px; color: var(--text-muted);
}
.idea-stats span { display: inline-flex; align-items: center; gap: 4px; }

/* ========== STORIES ========== */
.story-card {
  display: flex; gap: 14px;
  padding: 14px;
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: 10px;
  transition: all 200ms;
}
.story-card:hover { border-color: var(--border-light); }
.story-thumb {
  width: 100px; height: 80px;
  border-radius: 6px;
  flex-shrink: 0;
  background-size: cover; background-position: center;
}
.story-content { flex: 1; min-width: 0; }
.story-title { font-size: 14px; font-weight: 600; margin-bottom: 4px; line-height: 1.4; }
.story-meta { font-size: 11px; color: var(--text-muted); }

/* ========== TRENDING STOCKS ========== */
.trending-row {
  display: grid;
  grid-template-columns: auto 1fr auto auto auto;
  gap: 14px;
  padding: 12px 14px;
  border-bottom: 1px solid var(--border);
  align-items: center;
  font-size: 13px;
}
.trending-row:last-child { border: none; }
.trending-row:hover { background: rgba(255,255,255,0.02); }
.trending-row .ticker { font-weight: 700; }
.trending-row .company { color: var(--text-muted); font-size: 12px; }
.trending-row svg.spark { width: 70px; height: 24px; }
.trending-row .price { font-family: var(--font-mono); font-weight: 600; }

/* ========== Detail tabs ========== */
.detail-tabs {
  display: flex; gap: 0;
  background: var(--bg-elev);
  border: 1px solid var(--border);
  border-radius: 6px;
  overflow: hidden;
}
.detail-tabs button {
  padding: 6px 14px;
  font-size: 12px; font-weight: 500;
  color: var(--text-muted);
  border-right: 1px solid var(--border);
}
.detail-tabs button:last-child { border-right: none; }
.detail-tabs button.active { background: var(--accent); color: white; }

/* ========== INDICATORS LIST ========== */
.indicator-row {
  display: grid;
  grid-template-columns: auto 1fr auto;
  gap: 12px;
  padding: 12px 14px;
  border-bottom: 1px solid var(--border);
  align-items: center;
}
.indicator-row:last-child { border: none; }
.indicator-icon {
  width: 36px; height: 36px;
  border-radius: 8px;
  background: linear-gradient(135deg, var(--accent), #7c3aed);
  display: flex; align-items: center; justify-content: center;
  color: white;
}
.indicator-name { font-weight: 600; font-size: 13px; }
.indicator-author { color: var(--text-muted); font-size: 12px; }

/* ========== STATS BANNER ========== */
.stats-banner {
  background: linear-gradient(135deg, rgba(41,98,255,0.12), rgba(168,85,247,0.06));
  border: 1px solid var(--border);
  border-radius: 16px;
  padding: 40px;
  text-align: center;
}
.stats-banner h3 { font-size: 28px; margin-bottom: 8px; letter-spacing: -0.02em; }
.stats-banner p { color: var(--text-muted); margin-bottom: 28px; }
.stats-grid {
  display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px;
  max-width: 800px; margin: 0 auto;
}
.stats-grid .num {
  font-size: 36px; font-weight: 700; letter-spacing: -0.02em;
  background: linear-gradient(135deg, #5b8cff, #a855f7);
  -webkit-background-clip: text; -webkit-text-fill-color: transparent;
}
.stats-grid .lbl { font-size: 13px; color: var(--text-muted); margin-top: 4px; }

/* ========== CHART PAGE ========== */
.chart-layout {
  display: grid;
  grid-template-columns: 280px 1fr 320px;
  height: calc(100vh - 56px);
  border-top: 1px solid var(--border);
}
.watchlist-sidebar {
  background: var(--bg-elev);
  border-right: 1px solid var(--border);
  overflow-y: auto;
}
.watchlist-header {
  padding: 12px 14px;
  border-bottom: 1px solid var(--border);
  display: flex; align-items: center; justify-content: space-between;
  font-size: 12px; font-weight: 600;
  text-transform: uppercase; letter-spacing: 0.05em;
  color: var(--text-muted);
}
.accordion-group { border-bottom: 1px solid var(--border); }
.accordion-trigger {
  width: 100%;
  padding: 10px 14px;
  display: flex; align-items: center; justify-content: space-between;
  font-size: 12px; font-weight: 600;
  text-transform: uppercase; letter-spacing: 0.04em;
  color: var(--text-muted);
  background: transparent;
  transition: background 150ms;
}
.accordion-trigger:hover { background: var(--bg-elev-2); color: var(--text); }
.accordion-trigger .chev { transition: transform 200ms; }
.accordion-group.collapsed .accordion-trigger .chev { transform: rotate(-90deg); }
.accordion-group.collapsed .accordion-content { display: none; }
.accordion-content { padding-bottom: 6px; }

.watch-row {
  padding: 8px 14px;
  display: grid;
  grid-template-columns: 1fr auto auto;
  gap: 10px;
  font-size: 12px;
  align-items: center;
  cursor: pointer;
}
.watch-row:hover { background: var(--bg-elev-2); }
.watch-row .sym { font-weight: 600; }
.watch-row.active { background: rgba(41,98,255,0.15); border-left: 2px solid var(--accent); padding-left: 12px; }
.watch-row .last { font-family: var(--font-mono); }
.watch-row .ch { font-family: var(--font-mono); font-size: 11px; }

/* CHART MAIN */
.chart-main {
  display: flex; flex-direction: column;
  background: var(--bg);
  overflow: hidden;
}
.chart-toolbar {
  height: 48px;
  border-bottom: 1px solid var(--border);
  display: flex; align-items: center;
  padding: 0 14px;
  gap: 14px;
  background: var(--bg-elev);
}
.chart-symbol {
  display: flex; align-items: center; gap: 10px;
}
.chart-symbol .sym-icon { width: 32px; height: 32px; }
.chart-symbol .sym-text .name { font-size: 14px; font-weight: 700; }
.chart-symbol .sym-text .meta { font-size: 11px; color: var(--text-muted); }
.chart-price-bar {
  display: flex; align-items: baseline; gap: 8px;
}
.chart-price-bar .price { font-size: 22px; font-weight: 700; font-family: var(--font-mono); }
.chart-price-bar .chg { font-family: var(--font-mono); font-size: 13px; }

.chart-tools {
  display: flex; align-items: center; gap: 4px;
  margin-left: auto;
}
.chart-tools button {
  padding: 6px 10px;
  font-size: 12px;
