    <line x1="0" y1="${h*0.4}" x2="${w}" y2="${h*0.4}" stroke="#2962FF" stroke-dasharray="4 4" stroke-width="1" opacity="0.6"/>
    <line x1="0" y1="${h*0.7}" x2="${w}" y2="${h*0.7}" stroke="#a855f7" stroke-dasharray="4 4" stroke-width="1" opacity="0.5"/>
  </svg>`;
